const bridge = window.aster;
const demo = !bridge;
const $ = (s, el=document) => el.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = n => Number(n || 0);
const known = n => typeof n === 'number' && Number.isFinite(n);
const measure = n => known(n) ? fmt(n) : '—';
const mutationAllowed = method => can(method) && state.system?.capabilities?.[method] === true;
const fmt = (n, precision=1) => { n = num(n); if (!n) return '0 B'; const i = Math.min(Math.floor(Math.log(Math.abs(n))/Math.log(1024)),4); return `${(n/1024**i).toLocaleString(undefined,{maximumFractionDigits:precision})} ${['B','KB','MB','GB','TB'][i]}`; };
const day = value => value!==null&&value!==undefined&&Number.isFinite(new Date(value).getTime()) ? new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}) : 'Not available';
const sum = files => files.reduce((total,f)=>total+num(f.size),0);
const categories = {Video:{color:'#416f69',icon:'video'},Images:{color:'#89a59b',icon:'image'},Documents:{color:'#b7bba4',icon:'files'},Audio:{color:'#d6bb96',icon:'music'},Archives:{color:'#c28e77',icon:'archive'},Caches:{color:'#939ba7',icon:'folder'},Logs:{color:'#b5a6b8',icon:'files'},Other:{color:'#c4c9c4',icon:'files'}};
const nav = [{"id":"overview","name":"Home","icon":"overview","group":"WORKSPACE"},{"id":"recommendations","name":"Recommendations","icon":"shield","group":""},{"id":"storage","name":"Storage map","icon":"storage","group":"STORAGE"},{"id":"drives","name":"Drive overview","icon":"drive","group":""},{"id":"insights","name":"Storage insights","icon":"storage","group":""},{"id":"history","name":"Storage history","icon":"activity","group":""},{"id":"large","name":"Large files","icon":"files","group":""},{"id":"duplicates","name":"Duplicates","icon":"duplicates","group":""},{"id":"organize","name":"Organize files","icon":"folder","group":""},{"id":"cleanup","name":"Review junk files","icon":"cleanup","group":""},{"id":"performance","name":"Running processes","icon":"cpu","group":"SYSTEM"},{"id":"applications","name":"Installed apps","icon":"applications","group":""},{"id":"startup","name":"Startup apps","icon":"startup","group":""},{"id":"registry","name":"Registry files","icon":"files","group":""},{"id":"tools","name":"Windows tools","icon":"settings","group":""},{"id":"report","name":"System report","icon":"report","group":"YOUR TOOLS"},{"id":"activity","name":"Activity & restore","icon":"activity","group":""},{"id":"settings","name":"Settings","icon":"settings","group":""}];
nav.splice(1,0,{id:'footprints',name:'App disk usage',icon:'applications'},{id:'optimizer',name:'Performance review',icon:'cpu'});
nav.push(...[{id:'browser',name:'Browser data',icon:'shield'},{id:'tracking',name:'Change tracking',icon:'activity'},{id:'drivers',name:'Drivers',icon:'cpu'},{id:'updates',name:'Version review',icon:'applications'},{id:'maintenance',name:'Maintenance',icon:'check'}]);
nav.push({id:'startupControls',name:'Startup controls',icon:'startup'},{id:'managedUpdates',name:'Software updates',icon:'refresh'},{id:'registryLive',name:'Registry browser',icon:'files'},{id:'uninstall',name:'Tracked uninstall',icon:'applications'},{id:'recovery',name:'Changes & recovery',icon:'activity'});
let savedPreferences = {};
try { savedPreferences=JSON.parse(localStorage.getItem('aster-preferences')||'{}'); } catch {}
const state = {page:'overview',system:demo?demoSystem:null,scan:demo?demoScan:null,root:demo?demoScan.root:null,scanning:false,progress:{},selected:new Set(),search:'',filter:'all',extension:'all',age:'all',folder:'',previousScan:null,recommendations:null,diagnostics:null,diagnosticsError:null,sort:'size-desc',view:'map',apps:demo?demoApps:null,startup:demo?demoStartup:null,activity:[],loading:false,error:null,settings:{theme:'light',includeHidden:false,largeFileMinBytes:100*1024**2,excludedFolders:[],...savedPreferences},loaded:new Set(),busy:false};
state.insights=null;state.organizationPreview=null;state.performance=demo?{status:'sample',items:[{id:1,name:'Example browser',memoryBytes:250*1024**2,cpuSeconds:12},{id:2,name:'Example music player',memoryBytes:80*1024**2,cpuSeconds:5}],warnings:['Illustrative process data; not a reading of your computer.']}:null;state.registry={file:null,comparison:null};state.workbenchGroup='';state.toolSearch={};
let demoTimer;
let monitorTimer;
state.appView="grid";state.appSort="name";state.appPage=0;state.processSort="memory";state.processPage=0;state.performanceHistory=[];state.monitorPerformance=false;state.driveData=null;
state.care={};state.careQuery={};state.registryDraftText='';state.registryDraftValid=false;
let evidenceGeneration=0,scanGeneration=0;
const pageRequests=new Map(),pendingPages=new Map();
function invalidateEvidence(){evidenceGeneration++;state.uninstallResult=null;state.recommendations=null;state.loaded.delete('recommendations');for(const page of ['browser','tracking','footprints']){state.care[page]=null;state.loaded.delete(page);}}
const files = () => state.scan?.files || [];
const isCleanup = f => !!(f.cleanupReason || f.cleanup || f.category==='Caches' || f.category==='Logs');
const cleanup = () => files().filter(isCleanup);
const large = () => files().filter(f => f.size>=state.settings.largeFileMinBytes);
const duplicateGroups = () => { const groups = new Map(); for(const f of files()) if(f.duplicateGroup){if(!groups.has(f.duplicateGroup))groups.set(f.duplicateGroup,[]);groups.get(f.duplicateGroup).push(f);} return [...groups.values()].filter(g=>g.length>1); };
const duplicateBytes = () => duplicateGroups().reduce((n,g)=>n+sum(g)-Math.max(...g.map(f=>f.size)),0);
const scopedFiles = () => state.page==='cleanup' ? cleanup() : state.page==='large' ? large() : state.page==='duplicates' ? duplicateGroups().flat() : files();
const selectedFiles = () => files().filter(f=>state.selected.has(f.path));
const can = method => !demo && typeof bridge?.[method]==='function';
const workbenchUI=createWorkbench({icon,esc,fmt,pill,heading,empty,sectionHead,readOnlyBanner,platformWarnings,getState:()=>state,files,demo,can});
const studio=createStudio({icon,mark,esc,fmt,heading,pill,empty,platformWarnings,getState:()=>state,files,demo,can,storageInfo,groupStats,large,duplicateBytes});
const atelier=createAtelier({getState:()=>state,icon,mark,esc,fmt,heading,pill,empty,demo,can,call,render,toast,files,storageInfo,nav,scanProgress,renderPage});
const hub=createHub({entity:studio.entity,getState:()=>state,icon,mark,esc,fmt,heading,pill,empty,demo,can,call,render,toast,files,storageInfo,nav,scanProgress,renderPage});
const dashboard=createDashboard({getState:()=>state,icon,mark,esc,fmt,files,nav,renderPage,scanProgress,demo});
const management=createManagement({getState:()=>state,icon,esc,fmt,heading,pill,empty,call,render,toast,demo,entity:studio.entity,openModal,closeModal});
function toast(message,type='info'){const node=document.createElement('div');node.className=`toast ${type}`;node.innerHTML=`${icon(type==='error'?'warning':type==='success'?'check':'info')}<span>${esc(message)}</span>`;$('#notifications').append(node);setTimeout(()=>node.remove(),7000);}
async function call(method,arg){if(!can(method))throw new Error('This action needs the native Aster app.');const result=await bridge[method](arg);if(result?.ok===false)throw new Error(result.error?.message||result.error||'The action could not be completed.');return result?.ok===true && result.data!==undefined?result.data:result;}
function normalizedScan(result){const raw=result?.result||result?.scan||result||{};const list=raw.files||raw.entries||[];return {...raw,id:raw.id||raw.scanId,root:raw.root||state.root,files:list.map(f=>({...f,path:f.path||f.absolutePath,name:f.name||(f.path||'').split(/[\\/]/).pop(),size:num(f.size??f.bytes),category:categoryOf(f),modifiedAt:f.modifiedAt??f.mtime??f.mtimeMs,cleanupReason:f.cleanupReason||f.reason||f.cleanup?.reason,duplicateGroup:f.duplicateGroup||f.duplicateGroupId}))};}
function categoryOf(f){const value=String(f.category||f.type||'').toLowerCase();const aliases={image:'Images',images:'Images',video:'Video',audio:'Audio',document:'Documents',documents:'Documents',archive:'Archives',archives:'Archives',cache:'Caches',caches:'Caches',logs:'Logs'};if(aliases[value])return aliases[value];const ext=(f.name||f.path||'').split('.').pop().toLowerCase();if(/^(mov|mp4|mkv|avi|webm)$/.test(ext))return'Video';if(/^(jpg|jpeg|png|gif|tiff|tif|heic|webp|svg)$/.test(ext))return'Images';if(/^(mp3|wav|flac|aac|m4a)$/.test(ext))return'Audio';if(/^(zip|dmg|exe|pkg|gz|tar|7z|iso)$/.test(ext))return'Archives';if(ext==='log')return'Logs';if(/^(cache|tmp)$/.test(ext))return'Caches';if(/^(pdf|docx?|xlsx?|txt|md|fig|pptx?)$/.test(ext))return'Documents';return'Other';}
function tileInk(color){const rgb=color.match(/[a-f\d]{2}/gi).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722>.24?'#28392f':'#fffef5';}
function treemapLayout(items,x=0,y=0,width=1000,height=300){if(!items.length)return [];if(items.length===1)return [{...items[0],x:x/10,y:y/3,width:width/10,height:height/3}];const total=items.reduce((n,g)=>n+g.size,0);let pivot=1,weight=items[0].size;while(pivot<items.length-1&&weight<total/2){weight+=items[pivot].size;pivot++;}const ratio=weight/total;if(width>=height)return [...treemapLayout(items.slice(0,pivot),x,y,width*ratio,height),...treemapLayout(items.slice(pivot),x+width*ratio,y,width*(1-ratio),height)];return [...treemapLayout(items.slice(0,pivot),x,y,width,height*ratio),...treemapLayout(items.slice(pivot),x,y+height*ratio,width,height*(1-ratio))];}
function storageInfo(){const s=state.system?.storage||state.system?.disk;return known(s?.total)&&s.total>0&&known(s.free)?{total:s.total,free:s.free,used:known(s.used)?s.used:s.total-s.free}:null;}
function groupStats(){return Object.keys(categories).map(name=>({name,...categories[name],size:sum(files().filter(f=>f.category===name)),count:files().filter(f=>f.category===name).length})).filter(c=>c.size>0).sort((a,b)=>b.size-a.size);}
function pill(text,kind='neutral'){return `<span class="pill ${kind}">${esc(text)}</span>`;}
function sectionHead(title,description,action=''){return `<div class="section-heading"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${action}</div>`;}
function empty(title,description,action='choose-folder',label='Choose a folder'){return `<div class="empty-state"><span class="empty-icon">${icon('folder')}</span><h3>${title}</h3><p>${description}</p>${action?`<button class="button primary" data-action="${action}">${icon('folder')}${label}</button>`:''}</div>`;}
function shell(){return dashboard.shell();}
function render(){const active=document.activeElement;const focusData=active?.dataset?Object.entries(active.dataset).find(([key])=>['select','detail','folder','view','theme','category'].includes(key)):null;const focusId=active?.id;const selectionStart=document.activeElement?.selectionStart;$('#app').innerHTML=shell();document.documentElement.dataset.theme=state.settings.theme;studio.hydrateIcons();if(focusId){const el=document.getElementById(focusId);if(el){el.focus();if(el.setSelectionRange&&selectionStart!==null)try{el.setSelectionRange(selectionStart,selectionStart);}catch{}}}else if(focusData){const [key,value]=focusData;const el=[...document.querySelectorAll('button,input')].find(node=>node.dataset[key]===value);el?.focus();}}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
function scanButton(){return `<button class="button primary" data-action="scan" ${state.scanning?'disabled':''}>${icon(state.scan?'refresh':'search')}${demo?'Run sample scan':state.root?'Scan folder':'Choose a folder'}</button>`;}
function scanProgress(){const p=state.progress;return `<section class="scan-progress" aria-live="polite"><span class="scan-spinner"></span><div><strong>${p.phase==='hashing'?'Comparing file contents…':'Reading your selected folder…'}</strong><p>${num(p.files??p.filesScanned).toLocaleString()} files · ${fmt(p.bytes??p.bytesScanned)}${p.currentPath?' · '+esc(p.currentPath):''}</p><div class="progress-track"><span></span></div></div><button class="button small" data-action="cancel-scan">Cancel scan</button></section>`;}
function renderPage(){return ({overview:dashboard.home,startupControls:management.startups,managedUpdates:management.updates,registryLive:management.registry,uninstall:management.tracking,recovery:management.recovery,footprints:hub.footprints,optimizer:hub.optimizer,browser:atelier.browser,tracking:atelier.tracking,drivers:atelier.drivers,updates:atelier.updates,maintenance:atelier.maintenance,drives:studio.drives,history:studio.history,storage:storagePage,recommendations:recommendationsPage,insights:workbenchUI.insights,organize:workbenchUI.organization,performance:studio.performance,registry:()=>workbenchUI.registry()+atelier.editor(),tools:workbenchUI.tools,cleanup:()=>filePage('cleanup'),large:()=>filePage('large'),duplicates:duplicatesPage,startup:startupPage,applications:studio.applications,report:reportPage,activity:activityPage,settings:settingsPage}[state.page]||overviewPage)();}
function overviewPage(){return studio.overview();}
const extensionOf = f => { const name=f.name||''; const dot=name.lastIndexOf('.'); return dot>0?name.slice(dot+1).toLowerCase():'(none)'; };
const folderOf = f => String(f.path||'').replace(/\\/g,'/').split('/').slice(0,-1).join('/');
const scanPartial = scan => !!(scan?.analysis?.completeness==='partial'||scan?.cancelled||scan?.truncated||scan?.warnings?.length||scan?.warningsOmitted);
function resetFilters(){state.search='';state.filter='all';state.extension='all';state.age='all';state.folder='';}
function folderExplorer(){const root=String(state.scan?.root||'').replace(/\\/g,'/').replace(/\/$/,'');const current=state.folder||root;const children=new Map();for(const f of files()){const parent=folderOf(f);if(!parent.startsWith(current+'/'))continue;const child=parent.slice(current.length+1).split('/')[0];const path=current+'/'+child;const item=children.get(path)||{path,name:child,size:0,count:0};item.size+=f.size;item.count++;children.set(path,item);}const list=[...children.values()].sort((a,b)=>b.size-a.size);return `<div class="folder-explorer"><div class="folder-location"><span>${icon('folder')}<strong>${esc(current)}</strong></span>${state.folder?`<button class="text-button" data-folder="${esc(current.slice(0,current.lastIndexOf('/'))||root)}">Up one level</button><button class="text-button" data-folder="">All scanned folders</button>`:''}</div>${list.length?`<div class="folder-grid">${list.slice(0,30).map(f=>`<button class="folder-card" data-folder="${esc(f.path)}">${icon('folder')}<span><strong>${esc(f.name)}</strong><small>${f.count} files · ${fmt(f.size)}</small></span>${icon('chevron')}</button>`).join('')}</div>${list.length>30?'<p class="tiny-note">Showing the 30 largest child folders. Search file paths below to find the others.</p>':''}`:'<p class="tiny-note">No deeper folders with scanned files. The file list includes this folder and its descendants.</p>'}</div>`;}
function comparisonPanel(){const comparison=state.scan?.comparison;if(comparison){const t=comparison.totals||{};return `<section class="panel comparison-panel">${sectionHead('Changes between scans','Compared by the native scan engine',pill(comparison.comparable?'Comparable snapshots':'Limited comparison'))}<div class="comparison-grid"><div><strong>${num(t.addedFiles)}</strong><span>Newly observed</span></div><div><strong>${num(t.removedFiles)}</strong><span>No longer observed</span></div><div><strong>${num(t.changedFiles)}</strong><span>Changes detected</span></div><div><strong>${t.deltaBytes>0?'+':t.deltaBytes<0?'−':''}${fmt(Math.abs(t.deltaBytes||0))}</strong><span>Observed size difference</span></div></div>${[...(comparison.warnings||[]),...(comparison.notes||[])].map(note=>`<p class="tiny-note">${esc(note)}</p>`).join('')}</section>`;}const previous=demo?state.previousScan:null,current=state.scan;if(!previous||!current||previous.root!==current.root)return `<section class="panel comparison-panel">${sectionHead('Changes between scans','Run another scan of this folder to compare the two snapshots in this session.')}<p class="tiny-note">No background monitoring. Comparisons are held only for this session.</p></section>`;const before=new Map(previous.files.map(f=>[f.path,f])),after=new Map(current.files.map(f=>[f.path,f]));const added=current.files.filter(f=>!before.has(f.path)).length,removed=previous.files.filter(f=>!after.has(f.path)).length,changed=current.files.filter(f=>before.has(f.path)&&(before.get(f.path).size!==f.size||before.get(f.path).modifiedAt!==f.modifiedAt)).length;const delta=sum(current.files)-sum(previous.files);return `<section class="panel comparison-panel">${sectionHead('Changes between scans','Compared with the previous scan of this folder in this session',pill(scanPartial(previous)||scanPartial(current)?'Partial snapshots':'Session comparison'))}<div class="comparison-grid"><div><strong>${added}</strong><span>Newly observed</span></div><div><strong>${removed}</strong><span>No longer observed</span></div><div><strong>${changed}</strong><span>Size or date changed</span></div><div><strong>${delta>0?'+':delta<0?'−':''}${fmt(Math.abs(delta))}</strong><span>Observed size difference</span></div></div><p class="tiny-note">${scanPartial(previous)||scanPartial(current)?'At least one scan is incomplete. Missing files may have been skipped, and totals are not directly comparable. ':' '}Metadata comparison only. A file no longer observed is not proof of deletion; scan exclusions and access can change.</p></section>`;}
function recommendationsPage(){const groups=duplicateGroups(),candidates=cleanup(),big=large();const cards=[];if(groups.length)cards.push({title:'Compare matching copies',page:'duplicates',symbol:'duplicates',evidence:`${groups.length} content-match groups · ${fmt(duplicateBytes())} in additional copies`,detail:'Keep at least one copy and check which location your applications use. Matching contents do not establish which copy is dispensable.'});if(big.length)cards.push({title:'Start with the largest files',page:'large',symbol:'files',evidence:`${big.length} files at or above ${fmt(state.settings.largeFileMinBytes)} · ${fmt(sum(big))} total`,detail:'Size is an observation, not a reason to remove a file. Review originals, projects, and backups before considering any move.'});if(candidates.length)cards.push({title:'Review cache-like files and logs',page:'cleanup',symbol:'cleanup',evidence:`${candidates.length} candidates · ${fmt(sum(candidates))} total`,detail:'Names and extensions are hints. Aster does not verify ownership, regeneration, or whether a file is currently in use.'});if(!demo&&Array.isArray(state.recommendations)){cards.length=0;for(const r of state.recommendations){const evidence=r.evidence||{};const facts=[];if(known(evidence.files))facts.push(`${evidence.files} files`);if(known(evidence.groups))facts.push(`${evidence.groups} groups`);if(known(evidence.potentialBytes))facts.push(`${fmt(evidence.potentialBytes)} in additional copies`);if(known(evidence.freeBytes))facts.push(`${fmt(evidence.freeBytes)} available of ${fmt(evidence.totalBytes)}`);if(evidence.status)facts.push(`Coverage: ${evidence.status}`);cards.push({title:esc(r.title),detail:esc(r.detail),evidence:esc(facts.join(' · ')||'Based on available local observations'),page:nav.some(n=>n.id===r.action)?r.action:'storage',symbol:r.severity==='warning'?'warning':'info'});}}return `${heading('EVIDENCE, BEFORE ACTION','A considered next step.','Observations from your selected folder, with their limits made clear.',scanButton())}${!state.scan?empty('Recommendations need a little context','Choose a folder for a read-only scan. Aster will explain useful findings without a health score.'): `${scanWarnings()}<div class="recommendation-context">${pill(demo?'Illustrative sample evidence':scanPartial(state.scan)?'Partial scan evidence':'Current scan evidence')}<span>${files().length} files observed · ${fmt(sum(files()))} · ${esc(state.scan.root)}</span></div><div class="recommendation-grid">${cards.map(c=>`<article class="panel evidence-card"><span class="intro-icon">${icon(c.symbol)}</span><h2>${c.title}</h2><p class="evidence-line">${c.evidence}</p><p>${c.detail}</p><button class="text-link" data-page="${c.page}">Review evidence ${icon('arrow')}</button></article>`).join('')||empty('No review suggestions from this scan','This does not certify your system’s health. Explore the storage map or scan another folder.',null)}</div>${state.loading?'<p class="tiny-note" role="status">Reading local recommendations…</p>':''}${comparisonPanel()}<div class="notice">${icon('shield')}<span>These views overlap: a file may be large, cache-like, and a duplicate. Do not add their totals together. No files are selected automatically, and quarantine does not free disk blocks.</span></div>`}`;}
function fileToolbar(placeholder='Search this view…'){const list=scopedFiles();const extensions=[...new Set(list.map(extensionOf))].sort();return `<div class="file-toolbar"><label class="table-search">${icon('search')}<input id="file-search" type="search" aria-label="Search files" placeholder="${placeholder}" value="${esc(state.search)}"></label><div class="filter-controls"><select id="category-filter" aria-label="Filter by file type"><option value="all">All file types</option>${Object.keys(categories).filter(c=>list.some(f=>f.category===c)).map(c=>`<option ${state.filter===c?'selected':''}>${c}</option>`).join('')}</select><select id="extension-filter" aria-label="Filter by extension"><option value="all">All extensions</option>${extensions.map(e=>`<option value="${esc(e)}" ${state.extension===e?'selected':''}>${esc(e==='(none)'?'No extension':'.'+e)}</option>`).join('')}</select><select id="age-filter" aria-label="Filter by modification age"><option value="all">Any modified date</option>${[['30','Older than 30 days'],['180','Older than 6 months'],['365','Older than a year'],['unknown','Date unavailable']].map(([v,label])=>`<option value="${v}" ${state.age===v?'selected':''}>${label}</option>`).join('')}</select><select id="sort-order" aria-label="Sort files"><option value="size-desc" ${state.sort==='size-desc'?'selected':''}>Largest first</option><option value="size-asc" ${state.sort==='size-asc'?'selected':''}>Smallest first</option><option value="name" ${state.sort==='name'?'selected':''}>Name A–Z</option><option value="date" ${state.sort==='date'?'selected':''}>Recently modified</option></select><button class="text-button" data-action="reset-filters">Reset filters</button></div></div><p class="filter-summary" role="status">${filteredFiles(list).length} of ${list.length} files match${state.age!=='all'?' · Modified date does not show when a file was last used':''}</p>`;}
function filteredFiles(list=scopedFiles()){return list.filter(f=>(state.filter==='all'||f.category===state.filter)&&(state.extension==='all'||extensionOf(f)===state.extension)&&(!state.folder||folderOf(f)===state.folder||folderOf(f).startsWith(state.folder+'/'))&&(state.age==='all'||(state.age==='unknown'?f.modifiedAt==null||!Number.isFinite(new Date(f.modifiedAt).getTime()):f.modifiedAt!=null&&Number.isFinite(new Date(f.modifiedAt).getTime())&&Date.now()-new Date(f.modifiedAt).getTime()>=Number(state.age)*86400000))&&(!state.search||(f.name+' '+f.path).toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name):state.sort==='date'?new Date(b.modifiedAt||0)-new Date(a.modifiedAt||0):state.sort==='size-asc'?a.size-b.size:b.size-a.size);}
function fileTable(list=filteredFiles()){if(!list.length)return `<div class="table-empty">${icon('search')}<strong>No files in this view</strong><p>Try a different search, extension, age, or folder filter. No files are selected automatically.</p></div>`;return `<div class="table-scroll"><table class="file-table"><thead><tr><th class="check-cell">${state.page==='duplicates'?'<span class="sr-only">Select individual copies</span>':`<input type="checkbox" id="select-all" aria-label="Select visible files" ${list.slice(0,500).every(f=>state.selected.has(f.path))?'checked':''}>`}</th><th>Name <span class="table-count">${list.length}</span></th><th>Type</th><th>Modified</th><th class="align-right">Size</th><th><span class="sr-only">Details</span></th></tr></thead><tbody>${list.slice(0,500).map(f=>`<tr class="${state.selected.has(f.path)?'selected':''}"><td class="check-cell"><input type="checkbox" data-select="${esc(f.path)}" aria-label="Select ${esc(f.name)}" ${state.selected.has(f.path)?'checked':''}></td><td><button class="file-name-button" data-detail="${esc(f.path)}"><span class="file-type-icon" style="--file-color:${categories[f.category]?.color||'#aaa'}">${icon(categories[f.category]?.icon||'files')}</span><span><strong>${esc(f.name)}</strong><small title="${esc(f.path)}">${esc(f.path.slice(0,-f.name.length))}</small></span></button></td><td>${esc(f.category)}</td><td>${day(f.modifiedAt)}</td><td class="align-right file-size">${fmt(f.size)}</td><td><button class="icon-button" data-detail="${esc(f.path)}" aria-label="Details for ${esc(f.name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>${list.length>500?'<p class="tiny-note table-limit">Showing the first 500 matches. Narrow your search to see more.</p>':''}`;}
function selectionBar(){const selected=selectedFiles();return `<div class="selection-bar ${selected.length?'has-selection':''}"><div>${icon(selected.length?'check':'shield')}<span>${selected.length?`<strong>${selected.length} selected</strong><span class="selection-separator">·</span>${fmt(sum(selected))} to review`:'Nothing selected. You’re in control.'}</span>${selected.length?'<button class="text-button" data-action="clear-selection">Clear</button>':''}</div><button class="button ${selected.length?'primary':''}" data-action="review-selection" ${selected.length?'':'disabled'}>Review selection ${icon('arrow')}</button></div>`;}
function storagePage(){const stats=groupStats(),total=sum(files());return `${heading('STORAGE EXPLORER','Every file has a place.','See what’s here, then decide what deserves the room.',`<button class="button" data-action="choose-folder">${icon('folder')}Choose folder</button>${scanButton()}`)}${!state.scan?empty('Start with a place you know','Pick a folder to map its files. Your scan is read-only and stays on this computer.'): `<section class="panel storage-panel"><div class="storage-heading"><div class="root-label">${icon('folder')}<span><strong>${esc(state.scan.root)}</strong><small>${files().length.toLocaleString()} files · ${fmt(total)} scanned${state.scan.cancelled||state.scan.truncated?' · Partial scan':''}${demo?' · Sample data':''}</small></span></div>${can('exportInventory')?'<button class="button small" data-action="export-inventory">'+icon('download')+'Export CSV</button>':''}<div class="segmented" aria-label="Storage view"><button data-view="map" class="${state.view==='map'?'active':''}" aria-pressed="${state.view==='map'}">${icon('storage')}Map</button><button data-view="list" class="${state.view==='list'?'active':''}" aria-pressed="${state.view==='list'}">${icon('files')}List</button></div></div>${state.view==='map'?`<div class="treemap" role="group" aria-label="File type sizes in scanned folder">${treemapLayout(stats).map((g,i)=>`<button class="treemap-tile tile-${i} ${g.width<14||g.height<22?'tile-small':''}" style="--tile-color:${g.color};--tile-ink:${tileInk(g.color)};left:${g.x}%;top:${g.y}%;width:${g.width}%;height:${g.height}%" data-category="${g.name}" title="${g.name}: ${fmt(g.size)}" aria-label="Filter ${g.name}: ${fmt(g.size)}, ${g.count} files"><span>${icon(g.icon)}<strong>${g.name}</strong></span><span class="tile-size">${fmt(g.size)}</span><small>${g.count} ${g.count===1?'file':'files'} · ${(g.size/total*100).toFixed(1)}%</small></button>`).join('')}</div><div class="map-caption"><span>Relative area shows storage by file type</span><span>Click a category to explore ${icon('arrow')}</span></div>`:''}${folderExplorer()}${fileToolbar()}${fileTable()}${selectionBar()}</section>${scanWarnings()}`}`;}
function scanWarnings(){const warnings=[...new Set([...(state.scan?.warnings||[]),...(state.scan?.analysis?.warnings||[])])];if(state.scan?.cancelled)warnings.unshift('The scan was canceled; these results are incomplete.');else if(state.scan?.truncated)warnings.unshift('The scan reached a safety limit; these results are incomplete.');if(state.scan?.warningsOmitted)warnings.push(state.scan.warningsOmitted+' additional warnings were omitted.');return warnings.length?`<div class="notice">${icon('info')}<span><strong>Some items weren’t included.</strong> ${esc(warnings.map(w=>typeof w==='string'?w:w.message||w.path||'Item skipped').slice(0,4).join(' '))}</span></div>`:'';}
function filePage(type){const isClean=type==='cleanup';return `${heading(isClean?'LESS CLUTTER, MORE INTENTION':'A LITTLE PERSPECTIVE',isClean?'Make room, thoughtfully.':'Meet your larger files.',isClean?'Candidates for review, never a list of things you have to delete.':`Files over ${fmt(state.settings.largeFileMinBytes)} in your selected folder. Large doesn’t mean unnecessary.`,scanButton())}${!state.scan?empty('A closer look starts with a scan','Choose a folder and we’ll help you find places worth reviewing.'): `<div class="review-intro"><span class="intro-icon">${icon(isClean?'shield':'files')}</span><div><strong>${isClean?'Your files. Your final say.':'A big file can be an important file.'}</strong><p>${isClean?'Review the reason for each suggestion. Quarantine moves files aside so you can restore them; it does not free disk space.':'Preview each file before making a change. Project files, original media, and backups may be worth keeping.'}</p></div><div class="intro-stat"><strong>${fmt(sum(scopedFiles()))}</strong><span>${scopedFiles().length} files to explore</span></div></div><section class="panel">${fileToolbar()}${fileTable()}${selectionBar()}</section>${scanWarnings()}`}`;}
function duplicatesPage(){const groups=duplicateGroups();return `${heading('SAME CONTENT, DIFFERENT PLACES','Once might be enough.','Matching content helps you compare. The right copy is yours to choose.',scanButton())}${!state.scan?empty('Find out what’s here twice','A folder scan can compare file content without changing your files.'): `<div class="review-intro"><span class="intro-icon lavender">${icon('duplicates')}</span><div><strong>${groups.length} groups with matching content</strong><p>${demo?'These are illustrative sample matches.':'Matches are based on content hashes, not just file names.'} Always keep at least one copy. A copy’s location may matter to an application.</p></div><div class="intro-stat"><strong>${fmt(duplicateBytes())}</strong><span>additional copies</span></div></div>${scanWarnings()}<section class="panel duplicate-panel">${fileToolbar('Search matching files…')}${groups.length&&filteredFiles(groups.flat()).length?groups.map((group,i)=>{const visible=filteredFiles(group);return visible.length?`<div class="duplicate-group"><div class="duplicate-heading"><span>${icon('duplicates')}<strong>Match group ${i+1}</strong>${pill(group.length+' copies')}</span><span>${fmt(group[0].size)} each <span class="duplicate-dot">·</span> Keep one or more</span></div>${fileTable(visible)}</div>`:'';}).join(''):empty(groups.length?'No matching copies in this view':'No matching copies found',groups.length?'Reset the search and filters to see the reported groups.':scanPartial(state.scan)?'No groups were reported in the scanned subset. Coverage is incomplete.':'No duplicate groups were reported for this folder.',null)}${selectionBar()}</section>`}`;}
function osSettingsButton(key,label){return can('openSystemSettings')&&state.system?.capabilities?.nativePlatform!==false?`<button class="button" data-system-settings="${key}">${icon('external')}${label}</button>`:'';}
function readOnlyBanner(text){return `<div class="notice">${icon('shield')}<span>${text}</span></div>`;}
function startupPage(){const entries=Array.isArray(state.startup)?state.startup:state.startup?.entries||state.startup?.items||[];return `${heading('A CALMER START','Start with what you need.','Understand what launches when your computer starts.',`<button class="button" data-action="refresh-startup">${icon('refresh')}Refresh</button>${osSettingsButton('startup','Open system settings')}`)}${readOnlyBanner('This view is read-only. Manage startup behavior in your operating system’s settings; Aster won’t disable background services for you.')}<section class="panel inventory-panel">${sectionHead('Startup items',demo?'Example entries, not your computer':state.loading?'Reading startup configuration…':`${entries.length} items reported`)}${entries.length?`<div class="inventory-list">${entries.map(item=>`<div class="inventory-row">${studio.entity(item,'startup')}<div class="inventory-name"><strong>${esc(item.name||item.label)}</strong><p>${esc(item.description||item.path||item.command||'No additional details reported')}</p></div><span class="inventory-kind">${esc(item.duplicateCount>1?'Repeated target × '+item.duplicateCount:item.kind||item.type||'Startup entry')}</span>${pill(item.enabled===false?'Disabled':item.enabled===true?'Enabled':'Reported',item.enabled===true?'green':'neutral')}</div>`).join('')}</div>`:empty(state.loading?'Reading startup items…':'No startup items reported','Availability depends on your operating system and permissions.',null)}${platformWarnings(state.startup)}</section><div class="two-note-grid"><article class="small-note">${icon('info')}<h3>Background doesn’t mean bad</h3><p>Sync tools, audio drivers, and security software often need to run in the background.</p></article><article class="small-note">${icon('settings')}<h3>Make changes where they belong</h3><p>Use Login Items on macOS or Startup Apps in Windows Settings. Check the publisher before disabling an unfamiliar entry.</p></article></div>`;}
function appsPage(){return studio.applications();}
function platformWarnings(value){const warnings=value?.warnings||[];return warnings.length?`<div class="inventory-warning">${icon('info')}${esc(warnings.map(w=>typeof w==='string'?w:w.message).join(' '))}</div>`:'';}
function diagnosticsPanel(){const d=state.diagnostics;if(!d)return demo?'':`<section class="panel comparison-panel">${sectionHead('Additional system observations',state.diagnosticsError?esc(state.diagnosticsError):state.loading?'Reading local diagnostic sources…':'Additional diagnostic readings are unavailable.')}<p class="tiny-note">Unavailable data cannot establish system health. Refresh the report to try again.</p></section>`;return `<section class="panel comparison-panel">${sectionHead('Additional system observations',`Collected ${day(d.collectedAt)} · Read-only evidence`,pill(d.status||'Unknown coverage'))}<div class="report-grid"><section class="report-block"><h3>Volume capacity</h3>${(d.volumes?.items||[]).length?`<dl>${d.volumes.items.map(v=>`<div><dt>${esc(v.label||v.id)}</dt><dd>${measure(v.free)} free / ${measure(v.total)}</dd></div>`).join('')}</dl>`:'<p class="tiny-note">No volume capacity readings available</p>'}${platformWarnings(d.volumes)}</section><section class="report-block"><h3>Battery snapshot</h3><dl><div><dt>Charge</dt><dd>${known(d.battery?.chargePercent)?d.battery.chargePercent+'%':'Not reported'}</dd></div><div><dt>Power source</dt><dd>${esc(d.battery?.powerSource||'unknown')}</dd></div><div><dt>State</dt><dd>${esc(d.battery?.state||'unknown')}</dd></div></dl>${platformWarnings(d.battery)}</section><section class="report-block"><h3>Security assessment</h3>${pill('Not assessed')}<p class="tiny-note">${esc(d.security?.detail||'Security controls have not been assessed.')}</p></section><section class="report-block"><h3>Update availability</h3>${pill('Not checked')}<p class="tiny-note">${esc(d.updates?.detail||'Available updates have not been checked.')}</p></section></div>${platformWarnings(d)}</section>`;}
function reportPage(){const s=state.system, disk=storageInfo();return `${heading('THE FACTS, NICELY ARRANGED','Know your computer.','A local snapshot of your system, without a mystery health score.',`<button class="button" data-action="refresh-system">${icon('refresh')}Refresh</button><button class="button primary" data-action="export-report">${icon('download')}Export report</button>`)}${!s?empty('Your system report is loading','Aster reads basic hardware and operating system information.',null):`<div class="report-device panel"><span class="report-device-icon">${icon('computer')}</span><div><div class="eyebrow">${demo?'EXAMPLE COMPUTER':'THIS COMPUTER'}</div><h2>${esc(s.hostname||'Your computer')}</h2><p>${esc(s.osName||s.platform)} ${esc(s.version||'')} · ${esc(s.arch||'Architecture not reported')}</p></div>${pill(demo?'Demo data':'Local snapshot',demo?'amber':'green')}</div><div class="report-grid"><section class="panel report-block"><span class="block-icon">${icon('cpu')}</span><h3>Processor</h3><dl><div><dt>Model</dt><dd>${esc(s.cpu?.model||'Not reported')}</dd></div><div><dt>Logical cores</dt><dd>${s.cpu?.cores||'Not reported'}</dd></div><div><dt>Architecture</dt><dd>${esc(s.arch||'Not reported')}</dd></div></dl></section><section class="panel report-block"><span class="block-icon">${icon('memory')}</span><h3>Memory</h3><dl><div><dt>Installed</dt><dd>${s.memory?.total?fmt(s.memory.total):'Not reported'}</dd></div><div><dt>Available</dt><dd>${known(s.memory?.free)?fmt(s.memory.free):'Not reported'}</dd></div><div><dt>In use</dt><dd>${known(s.memory?.total)&&known(s.memory?.free)?fmt(s.memory.total-s.memory.free):'Not reported'}</dd></div></dl></section><section class="panel report-block"><span class="block-icon">${icon('drive')}</span><h3>Storage volume</h3><dl><div><dt>Capacity</dt><dd>${disk?fmt(disk.total):'Not reported'}</dd></div><div><dt>Available</dt><dd>${disk?fmt(disk.free):'Not reported'}</dd></div><div><dt>Used</dt><dd>${disk?fmt(disk.used):'Not reported'}</dd></div></dl></section><section class="panel report-block"><span class="block-icon">${icon('activity')}</span><h3>Session</h3><dl><div><dt>Uptime</dt><dd>${known(s.uptime)?Math.floor(s.uptime/86400)+'d '+Math.floor(s.uptime%86400/3600)+'h':'Not reported'}</dd></div><div><dt>Scan access</dt><dd>Selected folders only</dd></div><div><dt>Data destination</dt><dd>This computer</dd></div></dl></section></div>${s.recommendations?.length?`<section class="panel recommendation-panel">${sectionHead('Worth knowing','Reported observations, with context')}${s.recommendations.map(r=>`<article><span>${icon('info')}</span><div><h3>${esc(r.title)}</h3><p>${esc(r.detail)}</p></div></article>`).join('')}</section>`:''}`}${diagnosticsPanel()}${state.system?.measurementNotes?.length?readOnlyBanner(esc(state.system.measurementNotes.join(' '))):''}${readOnlyBanner('Available memory changes as applications work. macOS and Windows use memory differently; a busy memory meter alone is not a problem.')}`;}
function activityPage(){const entries=Array.isArray(state.activity)?state.activity:state.activity?.operations||state.activity?.entries||[];return `${heading('A CLEAR TRAIL','Every change, accounted for.','Review what happened and restore files that Aster moved aside.',`<button class="button" data-action="refresh-activity">${icon('refresh')}Refresh</button>`)}<div class="activity-summary"><span>${icon('activity')}</span><div><strong>${entries.length} ${entries.length===1?'operation':'operations'} recorded</strong><p>${demo?'This preview has not touched any files.':'Operation history is stored locally on this computer.'}</p></div><div class="activity-storage"><span>Disk space freed by quarantine</span><strong>0 B</strong></div></div><section class="panel activity-panel">${entries.length?entries.map(entry=>`<article class="activity-entry"><span class="activity-entry-icon">${icon(entry.status==='restored'?'refresh':'archive')}</span><div><h3>${esc(entry.label||entry.type||'Files moved to quarantine')}</h3><p>${day(entry.createdAt||entry.timestamp)} · ${(entry.files||entry.items||[]).length||entry.count||0} files · ${fmt(entry.totalBytes||entry.bytes||entry.size||0)}</p><small>${esc(entry.status||'Recorded')} ${entry.error?'· '+esc(entry.error):''}</small></div>${entry.status==='restored'?pill('Restored','green'):`<button class="button small" data-restore="${esc(entry.id||entry.operationId)}" ${mutationAllowed('restore')&&entry.canRestore!==false?'':'disabled'}>${icon('refresh')}Restore</button>`}</article>`).join(''):empty('A clean slate','Nothing has been moved. When you choose to quarantine files, you’ll find the history and restore controls here.',null)}</section><div class="notice">${icon('info')}<span><strong>Quarantine is a safety net, not extra disk space.</strong> Files are moved into a local holding folder. No permanent-delete action is available in Aster.</span></div>`;}
function settingsPage(){return `${heading('SETTLE IN','Make yourself at home.','A few considered preferences. No hidden maintenance routines.')}<section class="panel settings-panel">${sectionHead('Appearance','Set the tone for your workspace')}<div class="setting-row"><div><strong>Color theme</strong><p>Choose a light, dark, or system appearance</p></div><div class="segmented theme-selector">${['light','dark','system'].map(t=>`<button data-theme="${t}" class="${state.settings.theme===t?'active':''}" aria-pressed="${state.settings.theme===t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div></section><section class="panel settings-panel">${sectionHead('Folder scans','You choose the scope. Aster respects it.')}<div class="setting-row"><div><strong>Include dotfiles</strong><p>Includes names beginning with a dot. Windows Hidden attributes aren’t checked.</p></div><label class="switch"><input id="include-hidden" type="checkbox" ${state.settings.includeHidden?'checked':''} aria-label="Include dotfiles"><span></span></label></div><div class="setting-row"><div><strong>Large file threshold</strong><p>Show files above this size in Large files</p></div><select id="large-threshold" aria-label="Large file threshold">${[100,250,500,1024].map(m=>`<option value="${m*1024**2}" ${state.settings.largeFileMinBytes===m*1024**2?'selected':''}>${m===1024?'1 GB':m+' MB'}</option>`).join('')}</select></div></section><section class="panel settings-panel">${sectionHead('Scan exclusions','Skip relative folders inside the folder you choose')}<label class="tool-exclusions-label" for="scan-exclusions">One relative folder per line, for example node_modules or Cache</label><textarea id="scan-exclusions" class="tool-exclusions" rows="4">${esc((state.settings.excludedFolders||[]).join('\n'))}</textarea><button class="button" data-action="save-exclusions">Save exclusions</button><p class="tiny-note">Absolute paths, parent traversal and wildcard patterns are refused. Sensitive folders remain excluded.</p></section><section class="panel settings-panel">${sectionHead('A little peace of mind','Our defaults are deliberately cautious')}<div class="principle-row">${icon('shield')}<div><strong>Review before every change</strong><p>Aster never selects files or runs cleanup automatically</p></div>${pill('Always on','green')}</div><div class="principle-row">${icon('lock')}<div><strong>Your files stay local</strong><p>No cloud upload, analytics tracker, or account required</p></div>${pill('By design','green')}</div><div class="principle-row">${icon('activity')}<div><strong>A way back</strong><p>File moves are recorded and available to restore</p></div>${pill('Built in','green')}</div></section><div class="settings-footer">${mark()}<div><strong>Aster <span>${esc(state.system?.appVersion||'0.7.0 alpha')}</span></strong><p>A little room to breathe. ${demo?'You’re in Demo mode.':'Built for considered care.'}</p></div><button class="text-link" data-action="about">About Aster ${icon('arrow')}</button></div>`;}

function openModal(content){const modal=$('#modal');modal.innerHTML=`<button class="modal-close icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${content}`;modal.showModal();}
function closeModal(){const modal=$('#modal');if(modal.open)modal.close();}
function details(path){const f=files().find(f=>f.path===path);if(!f)return;openModal(`<div class="modal-symbol" style="--file-color:${categories[f.category]?.color}">${icon(categories[f.category]?.icon)}</div><div class="eyebrow">FILE DETAILS ${demo?'· DEMO DATA':''}</div><h2 id="modal-title">${esc(f.name)}</h2><p class="modal-path">${esc(f.path)}</p><dl class="file-details"><div><dt>Size</dt><dd>${fmt(f.size)}</dd></div><div><dt>Type</dt><dd>${esc(f.category)}</dd></div><div><dt>Last modified</dt><dd>${day(f.modifiedAt)}</dd></div><div><dt>Review level</dt><dd>${f.risk==='low'?'Lower-risk candidate':'Personal review needed'}</dd></div></dl><div class="modal-notice">${icon('info')}<span>${esc(f.cleanupReason||(isCleanup(f)?'The file extension suggests a cache or log, but Aster has not verified its owner or whether it can be regenerated. Review it personally.':'This may be an original, project file, or backup. File size alone does not make it unnecessary. Verify what uses this file before moving it.'))}</span></div>${f.duplicateGroup?'<p class="tiny-note">A matching copy was reported. Keep at least one copy and check which location your applications use.</p>':''}<div class="modal-actions"><button class="button" data-reveal="${esc(f.path)}" ${can('revealPath')?'':'disabled'}>${icon('external')}Show in folder</button><button class="button primary" data-select-detail="${esc(f.path)}">${state.selected.has(f.path)?'Deselect file':'Select for review'}</button></div>`);}
async function chooseFolder(){if(state.scanning){toast('Cancel the current scan before choosing another folder.');return;}if(demo){openModal(`<div class="modal-symbol">${icon('folder')}</div><div class="eyebrow">DEMO MODE</div><h2 id="modal-title">Your files aren’t connected.</h2><p>This browser preview uses a clearly labeled sample folder. Folder selection is available in the native desktop app.</p><div class="modal-notice">${icon('shield')}<span>No files have been read or changed on your computer.</span></div><div class="modal-actions"><button class="button" data-action="close-modal">Keep exploring</button><button class="button primary" data-action="sample-scan">Run sample scan ${icon('arrow')}</button></div>`);return;}try{const selected=await call('selectFolder');const root=typeof selected==='string'?selected:selected?.path||selected?.root;if(root){state.root=root;state.selected.clear();state.scan=null;state.previousScan=null;resetFilters();render();await startScan();}}catch(e){toast(e.message,'error');}}
async function startScan(){if(state.scanning)return;if(!state.root){await chooseFolder();return;}closeModal();const previous=state.scan;const requestGeneration=++scanGeneration;invalidateEvidence();state.error=null;state.scanning=true;resetFilters();state.progress={files:0,bytes:0};state.selected.clear();render();if(demo){let tick=0;demoTimer=setInterval(()=>{tick++;state.progress={files:Math.round(demoScan.files.length*Math.min(tick/7,1)),bytes:sum(demoScan.files)*Math.min(tick/7,1),currentPath:'Sample folder',phase:tick>4?'hashing':'scanning'};if(tick>=7){clearInterval(demoTimer);if(requestGeneration!==scanGeneration)return;invalidateEvidence();state.previousScan=previous;state.scan={...demoScan};state.scanning=false;toast('Sample scan complete. Your real files were not accessed.');}render();},320);return;}try{const result=await call('scan',{root:state.root,includeHidden:state.settings.includeHidden});if(requestGeneration!==scanGeneration)return;invalidateEvidence();state.previousScan=previous;state.scan=normalizedScan(result);state.insights=null;state.organizationPreview=null;state.loaded.delete('insights');state.loaded.delete('history');if(state.scan.root)state.root=state.scan.root;toast(scanPartial(state.scan)?'Scan finished with incomplete coverage. Review the scan notes.':`Scan complete. ${files().length.toLocaleString()} files reviewed.`,'success');}catch(e){state.error=e.message+(previous?' The previous scan remains visible; it is not a new result.':'');toast(e.message,'error');}finally{state.scanning=false;render();if(['recommendations','insights','history','browser','tracking','footprints'].includes(state.page))await loadPage(state.page,true);}}
async function cancelScan(){if(demo){clearInterval(demoTimer);state.scanning=false;render();toast('Sample scan stopped. No files were changed.');return;}try{await call('cancelScan');toast('Stopping the scan…');}catch(e){toast(e.message,'error');}}
async function reviewSelection(){if(state.busy)return;const chosen=selectedFiles();if(!chosen.length)return;const unsafeGroup=duplicateGroups().find(g=>g.every(f=>state.selected.has(f.path)));if(unsafeGroup){toast('Keep at least one file in each duplicate group. Deselect the copy you want to keep.','error');return;}state.busy=true;const reviewButton=$('[data-action="review-selection"]');if(reviewButton){reviewButton.disabled=true;reviewButton.textContent='Preparing review…';}let preview=null,error=null;try{if(!demo)preview=await call('previewQuarantine',{scanId:state.scan.id,paths:chosen.map(f=>f.path)});}catch(e){error=e.message;}state.busy=false;if(reviewButton){reviewButton.disabled=false;reviewButton.innerHTML='Review selection '+icon('arrow');}const previewId=preview?.previewId||preview?.id;const allowed=!!previewId&&mutationAllowed('quarantine')&&preview?.canExecute===true&&!error;const blockedReason=preview?.blockedReason||state.system?.capabilities?.mutationReason||(!demo&&!allowed&&!error?'File moves are unavailable in this build.':null);const warnings=preview?.warnings||[];openModal(`<div class="modal-symbol">${icon('archive')}</div><div class="eyebrow">${demo?'DEMO PREVIEW':'REVIEW BEFORE MOVING'}</div><h2 id="modal-title">Set ${chosen.length} ${chosen.length===1?'file':'files'} aside?</h2><p>Move the selected files into Aster’s local quarantine. You can restore them from Activity & restore.</p><div class="confirmation-stats"><span><small>Selected size</small><strong>${fmt(sum(chosen))}</strong></span><span><small>Disk space freed</small><strong>0 B</strong></span></div><div class="confirmation-files">${chosen.slice(0,8).map(f=>`<div>${icon(categories[f.category]?.icon)}<span>${esc(f.name)}</span><strong>${fmt(f.size)}</strong></div>`).join('')}${chosen.length>8?`<p>And ${chosen.length-8} more files</p>`:''}</div><div class="modal-notice">${icon('warning')}<span>Close any application using these files first. Moving original or project files may interrupt your work. Quarantine uses space on the same volume.</span></div>${warnings.map(w=>`<p class="tiny-note">${esc(typeof w==='string'?w:w.message)}</p>`).join('')}${blockedReason?`<div class="notice">${icon('lock')}<span><strong>Read-only alpha.</strong> ${esc(blockedReason)}</span></div>`:''}${error?`<div class="notice error">${icon('warning')}<span>${esc(error)}</span></div>`:''}${demo?'<div class="demo-dialog-note">Demo mode: this is a preview only. Moving files is disabled.</div>':''}<div class="modal-actions"><button class="button" data-action="close-modal">Keep files in place</button><button class="button primary" data-quarantine="${esc(previewId||'')}" ${allowed?'':'disabled'}>${icon('archive')}Move to quarantine</button></div>`);}
async function quarantine(previewId){if(!mutationAllowed('quarantine')||!previewId)return;const button=$('[data-quarantine]');button.disabled=true;button.textContent='Moving files…';try{const result=await call('quarantine',{previewId});if(result?.cancelled||result?.canceled){closeModal();toast('File move canceled. Your files are unchanged.');return;}closeModal();state.selected.clear();state.scan=null;await loadActivity();state.page='activity';render();toast(result?.message||'File move recorded. Review the operation below.','success');}catch(e){toast(e.message,'error');button.disabled=false;button.textContent='Move to quarantine';}}
function restoreDialog(id){openModal(`<div class="modal-symbol">${icon('refresh')}</div><div class="eyebrow">RESTORE FILES</div><h2 id="modal-title">Put these files back?</h2><p>Aster will restore the files in this operation to their original locations. Existing files won’t be overwritten; any conflicts will be reported.</p><div class="modal-actions"><button class="button" data-action="close-modal">Cancel</button><button class="button primary" data-restore-confirm="${esc(id)}">${icon('refresh')}Restore files</button></div>`);}
async function restore(id){const entries=Array.isArray(state.activity)?state.activity:state.activity?.operations||state.activity?.entries||[];const entry=entries.find(e=>(e.id||e.operationId)===id);if(!mutationAllowed('restore')||!entry||entry.canRestore===false)return;const button=$('[data-restore-confirm]');button.disabled=true;button.textContent='Restoring…';try{const result=await call('restore',{operationId:id});if(result?.cancelled||result?.canceled){closeModal();toast('Restore canceled.');return;}closeModal();await loadActivity();render();toast(result?.message||'Restore finished. Check the operation for details.','success');}catch(e){toast(e.message,'error');button.disabled=false;button.textContent='Restore files';}}
async function loadActivity(){if(can('getActivity'))state.activity=await call('getActivity');}
async function loadPage(page,force=false){
  if(demo||state.loaded.has(page)&&!force&&!['insights','organize','history','browser','tracking','maintenance','footprints','optimizer','startupControls','managedUpdates','uninstall','recovery'].includes(page))return;
  const methods={startupControls:'getStartupControls',managedUpdates:'getManagedUpdates',uninstall:'getTrackedUninstalls',recovery:'getManagementHistory',footprints:'getApplicationFootprints',optimizer:'getPerformanceAdvice',browser:'getBrowserReview',tracking:'getInstallTracking',drivers:'getDrivers',updates:'getUpdateReview',maintenance:'getMaintenance',drives:'getDiagnostics',history:'getStorageInsights',insights:'getStorageInsights',organize:'getOrganizationPreview',performance:'getPerformance',registry:'getRegistryData',recommendations:'getRecommendations',startup:can('getStartupReview')?'getStartupReview':'listStartup',applications:'listApplications',report:'getSystemInfo',activity:'getActivity'};
  const method=methods[page];if(!method||!can(method))return;
  const request=(pageRequests.get(page)||0)+1, evidence=evidenceGeneration;
  pageRequests.set(page,request);pendingPages.set(page,request);
  const current=()=>pageRequests.get(page)===request&&(!['recommendations','browser','tracking','footprints'].includes(page)||evidence===evidenceGeneration);
  state.loading=pendingPages.has(state.page);render();
  try{
    const result=await call(method);if(!current())return;if(page==='uninstall'&&can('listApplications')){const apps=await call('listApplications');if(!current())return;state.apps=apps;}
    let diagnostics=null,diagnosticsError=null;
    if(page==='report'&&can('getDiagnostics')){
      try{diagnostics=await call('getDiagnostics');}catch(error){diagnosticsError=error.message;}
      if(!current())return;
    }
    if(['browser','tracking','drivers','updates','maintenance','footprints','optimizer','startupControls','managedUpdates','uninstall','recovery'].includes(page))state.care[page]=result;
    if(page==='insights'||page==='history')state.insights=result;
    if(page==='drives')state.driveData=result;
    if(page==='organize')state.organizationPreview=result;
    if(page==='performance'){state.performance=result;if(!state.performanceHistory.some(p=>p.collectedAt===result.collectedAt)){state.performanceHistory.push({collectedAt:result.collectedAt,cpuPercent:result.cpuPercent??null});state.performanceHistory=state.performanceHistory.slice(-60);}}
    if(page==='registry')state.registry=result;
    if(page==='recommendations')state.recommendations=result;
    if(page==='startup')state.startup=result;
    if(page==='applications')state.apps=result;
    if(page==='report'){state.system=result;state.diagnostics=diagnostics;state.diagnosticsError=diagnosticsError;}
    if(page==='activity')state.activity=result;
    state.loaded.add(page);
    if(['startup','applications','report'].includes(page))invalidateEvidence();
  }catch(e){if(current())toast(e.message,'error');}
  finally{if(pendingPages.get(page)===request)pendingPages.delete(page);state.loading=pendingPages.has(state.page);render();}
}
async function navigate(page){if(!nav.some(n=>n.id===page))return;state.page=page;if(page!=='performance'){state.monitorPerformance=false;clearTimeout(monitorTimer);}state.loading=pendingPages.has(page);resetFilters();state.selected.clear();location.hash=page;render();$('#main').scrollTop=0;$('#main').focus();document.body.classList.remove('sidebar-open');await loadPage(page);}
async function setSettings(patch){const previous={...state.settings};state.settings={...state.settings,...patch};try{if(can('updateSettings')){const result=await call('updateSettings',patch);if(result)state.settings={...state.settings,...result};}localStorage.setItem('aster-preferences',JSON.stringify(state.settings));if(patch.largeFileMinBytes!==undefined&&previous.largeFileMinBytes!==state.settings.largeFileMinBytes)invalidateEvidence();render();return true;}catch(e){state.settings=previous;render();toast(e.message,'error');return false;}}
function about(){openModal(`<div class="about-mark">${mark()}</div><div class="eyebrow">ASTER ${esc(state.system?.appVersion||'0.7.0 ALPHA')}</div><h2 id="modal-title">A little room to breathe.</h2><p>Aster helps you understand your computer’s storage and make considered choices about your files.</p><div class="about-principles"><span>${icon('shield')}Read-only scans first</span><span>${icon('lock')}Files stay on your device</span><span>${icon('activity')}Reviewable, reversible file moves</span></div>${demo?'<div class="demo-dialog-note"><strong>You’re in Demo mode.</strong> All file names, system information, and findings are examples. This browser preview cannot scan, move, or restore your real files.</div>':'<div class="modal-notice"><span>This is an early local desktop build. No permanent deletion, automatic application removal, or system-service changes are offered.</span></div>'}<div class="modal-actions"><button class="button primary" data-action="close-modal">Back to Aster</button></div>`);}
async function exportReport(){try{if(can('exportReport')){const result=await call('exportReport');if(result?.canceled||result?.cancelled)return;toast(result?.path?'Report saved to '+result.path:'Report export completed.','success');return;}const report={application:'Aster',demo,generatedAt:new Date().toISOString(),system:state.system,scan:state.scan?{root:state.scan.root,files:files().length,bytes:sum(files()),warnings:state.scan.warnings}:null,notice:demo?'ILLUSTRATIVE SAMPLE DATA — not a report about your computer':'Local system snapshot'};const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=demo?'aster-demo-report.json':'aster-system-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(demo?'Sample report download requested. It is labeled as demo data.':'Report download requested.');}catch(e){toast(e.message,'error');}}

// Event delegation keeps all controls functional across page renders.
document.addEventListener('click',async event=>{const target=event.target.closest('button,a[data-page]');if(!target||target.disabled)return;try{if(target.tagName==='A'&&target.dataset.page)event.preventDefault();if(target.dataset.action?.startsWith('manage-')){await management.handle(target.dataset.action,target);return;}if(target.dataset.action?.startsWith('hub-')){await hub.handle(target.dataset.action,target);return;}if(target.dataset.action?.startsWith('care-')){await atelier.handle(target.dataset.action,target);return;}if(target.dataset.folderReview){await navigate('storage');state.folder=target.dataset.folderReview.replace(/\\/g,'/');state.view='list';render();return;}if(target.dataset.commandPage){closeModal();await navigate(target.dataset.commandPage);return;}if(target.dataset.appDetail!==undefined){const content=studio.appDetails(target.dataset.appDetail);if(content){openModal(content);studio.hydrateIcons();}return;}if(target.dataset.appView){state.appView=target.dataset.appView;render();return;}if(target.dataset.listPage){const [kind,page]=target.dataset.listPage.split(':');if(kind==='apps')state.appPage=Math.max(0,Number(page)||0);else state.processPage=Math.max(0,Number(page)||0);render();return;}if(target.dataset.refreshTool){await loadPage(target.dataset.refreshTool,true);return;}if(target.dataset.workbenchGroup){state.workbenchGroup=target.dataset.workbenchGroup;render();return;}if(target.dataset.page){await navigate(target.dataset.page);return;}if(Object.hasOwn(target.dataset,'folder')){state.folder=target.dataset.folder;state.view='list';render();return;}if(target.dataset.view){state.view=target.dataset.view;render();return;}if(target.dataset.category){state.filter=target.dataset.category;state.view='list';render();return;}if(target.dataset.detail){details(target.dataset.detail);return;}if(target.dataset.selectDetail){const path=target.dataset.selectDetail;state.selected.has(path)?state.selected.delete(path):state.selected.add(path);closeModal();render();return;}if(target.dataset.reveal){await call('revealPath',target.dataset.reveal);return;}if(target.dataset.quarantine){await quarantine(target.dataset.quarantine);return;}if(target.dataset.restore){restoreDialog(target.dataset.restore);return;}if(target.dataset.restoreConfirm){await restore(target.dataset.restoreConfirm);return;}if(target.dataset.systemSettings){await call('openSystemSettings',target.dataset.systemSettings);return;}if(target.dataset.theme){await setSettings({theme:target.dataset.theme});return;}switch(target.dataset.action){case'command-palette':openCommands();break;case'toggle-monitor':state.monitorPerformance=!state.monitorPerformance;clearTimeout(monitorTimer);render();if(state.monitorPerformance){await loadPage('performance',true);scheduleMonitor();}break;case'export-inventory':{const result=await call('exportInventory');if(!result.cancelled)toast('File inventory saved. The CSV contains local file paths.','success');break;}case'open-registry':case'compare-registry':{const result=await call(target.dataset.action==='open-registry'?'openRegistryFile':'compareRegistryFile');if(!result.cancelled){state.registry=result;state.registryDraftText='';state.registryDraftValid=false;state.registryDraftResult=null;render();}break;}case'preview-organization':{const mode=$('#organization-mode')?.value||'category';if(demo){state.organizationPreview={mode,proposals:[],skipped:[],warnings:['Organization previews require a native folder scan.']};toast('This demonstration does not propose changes to real files.');}else state.organizationPreview=await call('getOrganizationPreview',{mode});render();break;}case'export-organization':{const result=await call('exportOrganizationPlan',{mode:state.organizationPreview?.mode||'category'});if(!result.cancelled)toast('Local organization plan saved. No files were moved.','success');break;}case'save-exclusions':{const excludedFolders=($('#scan-exclusions')?.value||'').split(/\r?\n/).map(p=>p.trim()).filter(Boolean);if(await setSettings({excludedFolders}))toast('Folder exclusions saved. They apply to your next scan.');break;}case'reset-filters':resetFilters();render();break;case'choose-folder':await chooseFolder();break;case'scan':case'sample-scan':await startScan();break;case'cancel-scan':await cancelScan();break;case'close-modal':closeModal();break;case'about':about();break;case'clear-selection':state.selected.clear();render();break;case'review-selection':await reviewSelection();break;case'refresh-startup':await loadPage('startup',true);if(demo)toast('You’re viewing sample startup items.');break;case'refresh-applications':await loadPage('applications',true);if(demo)toast('You’re viewing sample applications.');break;case'refresh-system':await loadPage('report',true);if(demo)toast('You’re viewing a sample system report.');break;case'refresh-activity':await loadPage('activity',true);if(demo)toast('No real file operations have been performed.');break;case'export-report':await exportReport();break;case'dismiss-error':state.error=null;render();break;case'menu':document.body.classList.toggle('sidebar-open');break;}}catch(e){toast(e.message,'error');}});
document.addEventListener('input',event=>{if(event.target.id==='command-query'){const query=event.target.value.toLowerCase();for(const row of document.querySelectorAll('[data-command-name]'))row.hidden=!row.dataset.commandName.includes(query);return;}if(['process-search','registry-search'].includes(event.target.id)){state.toolSearch[event.target.id==='process-search'?'performance':'registry']=event.target.value;state.processPage=0;render();return;}if(['file-search','global-search','app-search'].includes(event.target.id)){state.search=event.target.value;state.appPage=0;if(event.target.id==='global-search'&&!['storage','large','cleanup','duplicates','applications'].includes(state.page)){state.page='storage';state.view='list';location.hash='storage';}render();}});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='app-sort'){state.appSort=el.value;state.appPage=0;render();}if(el.id==='process-sort'){state.processSort=el.value;state.processPage=0;render();}if(el.dataset.select){el.checked?state.selected.add(el.dataset.select):state.selected.delete(el.dataset.select);render();}if(el.id==='select-all'){filteredFiles().slice(0,500).forEach(f=>el.checked?state.selected.add(f.path):state.selected.delete(f.path));render();}if(el.id==='category-filter'){state.filter=el.value;render();}if(el.id==='extension-filter'){state.extension=el.value;render();}if(el.id==='age-filter'){state.age=el.value;render();}if(el.id==='sort-order'){state.sort=el.value;render();}if(el.id==='include-hidden')await setSettings({includeHidden:el.checked});if(el.id==='large-threshold')await setSettings({largeFileMinBytes:num(el.value)});});
document.addEventListener('input',event=>{atelier.input(event);hub.input(event);});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openCommands();return;}if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){event.preventDefault();($('#hub-tool-search')||$('#global-search'))?.focus();}if(event.key==='Escape')document.body.classList.remove('sidebar-open');});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(page!==state.page&&nav.some(n=>n.id===page))navigate(page);});
function openCommands(){closeModal();openModal(studio.commandPalette(nav));$('#command-query')?.focus();}
function scheduleMonitor(){clearTimeout(monitorTimer);if(!state.monitorPerformance||state.page!=='performance'||document.hidden)return;monitorTimer=setTimeout(async()=>{if(!state.monitorPerformance||state.page!=='performance'||document.hidden)return;if(!pendingPages.has('performance'))await loadPage('performance',true);scheduleMonitor();},5000);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(monitorTimer);else scheduleMonitor();});
async function init(){const page=location.hash.slice(1);if(nav.some(n=>n.id===page))state.page=page;render();if(!demo){if(can('onChooseFolderRequested'))bridge.onChooseFolderRequested(()=>chooseFolder());if(can('onScanProgress'))bridge.onScanProgress(progress=>{if(state.scanning){state.progress=progress;render();}});try{const results=await Promise.allSettled([can('getSystemInfo')?call('getSystemInfo'):Promise.resolve(null),can('getSettings')?call('getSettings'):Promise.resolve({})]);if(results[0].status==='fulfilled')state.system=results[0].value;else state.error=results[0].reason.message;if(results[1].status==='fulfilled')state.settings={...state.settings,...results[1].value};render();await loadPage(state.page);}catch(e){state.error=e.message;render();}}}
init();
